const heroSwiperElement=document.querySelector(".swiper-slider"),swiperNavigationButtonsElement=document.querySelector(".swiper-navigation-buttons");new Swiper(".swiper-slider",{spaceBetween:50,slidesPerView:1,loop:!0,autoplay:{delay:5e3},pagination:{el:".swiper-pagination",clickable:"true"},navigation:{nextEl:".swiper-button-next",prevEl:".swiper-button-prev"}});heroSwiperElement.addEventListener("mouseenter",function(){swiperNavigationButtonsElement.classList.remove("opacity-0")});heroSwiperElement.addEventListener("mouseleave",function(){swiperNavigationButtonsElement.classList.add("opacity-0")});